//! Non-ASCII advances of the characters each measured face maps.
//!
//! Generated from `tools/font-chain-reference/cmap-advances-g2/`. Each row is
//! `(scalar, font units)` at 2048 units per em. Printable ASCII stays in the
//! `[u16; 95]` tables. The drift gate rebuilds these rows from the TSV files.

pub(super) struct CmapSlots {
    pub plain: &'static [(u32, u16)],
    pub bold: &'static [(u32, u16)],
    pub italic: &'static [(u32, u16)],
    pub bold_italic: &'static [(u32, u16)],
}

impl CmapSlots {
    pub(super) fn slot(&self, bold: bool, italic: bool) -> &'static [(u32, u16)] {
        match (bold, italic) {
            (false, false) => self.plain,
            (true, false) => self.bold,
            (false, true) => self.italic,
            (true, true) => self.bold_italic,
        }
    }
}

